+// NewPortStat parses a listening address and port.
+func NewPortStat(ipPort string) (*PortStat, error) {
+	if ipPort == "" {
+		return &PortStat{}, nil
+	}
+	host, port, err := net.SplitHostPort(ipPort)
+	if err != nil || host == "" || port == "" {
+		return nil, fmt.Errorf("invalid listening port %q", ipPort)
+	}
+	if host != "*" && net.ParseIP(host) == nil {
+		return nil, fmt.Errorf("invalid listening address %q", host)
+	}
+	if n, err := strconv.Atoi(port); err != nil || n < 0 || n > 65535 {
+		return nil, fmt.Errorf("invalid listening port %q", port)
+	}
